create table if not exists public.shop_products (id uuid primary key default gen_random_uuid(),sku text not null unique,slug text not null unique,name text not null,name_ckb text not null,name_ar text not null,description text,description_ckb text,description_ar text,category text not null default 'general',image_url text,price_usd numeric(12,2) not null check(price_usd>=0),compare_at_usd numeric(12,2),inventory_count integer not null default 0 check(inventory_count>=0),reserved_count integer not null default 0 check(reserved_count>=0 and reserved_count<=inventory_count),is_active boolean not null default true,featured boolean not null default false,sort_order integer not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shop_orders (id uuid primary key default gen_random_uuid(),order_number text not null unique default ('GC-SHOP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),customer_user_id uuid not null references auth.users(id) on delete restrict,status text not null default 'pending' check(status in ('pending','confirmed','packed','in_transit','delivered','cancelled')),currency text not null default 'USD',subtotal_usd numeric(12,2) not null default 0,delivery_usd numeric(12,2) not null default 0,total_usd numeric(12,2) not null default 0,customer_name text not null,customer_phone text not null,delivery_address text not null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shop_order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.shop_orders(id) on delete cascade,product_id uuid not null references public.shop_products(id) on delete restrict,sku text not null,product_name text not null,image_url text,unit_price_usd numeric(12,2) not null,quantity integer not null check(quantity>0),line_total_usd numeric(12,2) not null,created_at timestamptz not null default now());
create index if not exists shop_products_active_idx on public.shop_products(is_active,featured,sort_order); create index if not exists shop_orders_customer_idx on public.shop_orders(customer_user_id,created_at desc); create index if not exists shop_order_items_order_idx on public.shop_order_items(order_id);
alter table public.shop_products enable row level security; alter table public.shop_orders enable row level security; alter table public.shop_order_items enable row level security;
drop policy if exists shop_products_public_read on public.shop_products; create policy shop_products_public_read on public.shop_products for select using(is_active=true);
drop policy if exists shop_orders_customer_read on public.shop_orders; create policy shop_orders_customer_read on public.shop_orders for select using(customer_user_id=auth.uid() or exists(select 1 from public.staff s where s.id=auth.uid() and s.is_active=true));
drop policy if exists shop_order_items_customer_read on public.shop_order_items; create policy shop_order_items_customer_read on public.shop_order_items for select using(exists(select 1 from public.shop_orders o where o.id=order_id and (o.customer_user_id=auth.uid() or exists(select 1 from public.staff s where s.id=auth.uid() and s.is_active=true))));
revoke all on public.shop_products from anon,authenticated; grant select on public.shop_products to anon,authenticated; revoke all on public.shop_orders,public.shop_order_items from anon,authenticated; grant select on public.shop_orders,public.shop_order_items to authenticated;
create or replace function public.shop_place_order(p_items jsonb,p_customer_name text,p_customer_phone text,p_delivery_address text,p_notes text default null) returns table(order_id uuid,order_number text,total_usd numeric) language plpgsql security definer set search_path=public as $$declare v_user uuid:=auth.uid(); v_order_id uuid; v_order_number text; v_subtotal numeric(12,2):=0; v_product public.shop_products%rowtype; v_item jsonb; v_product_id uuid; v_quantity integer; v_line numeric(12,2); begin if v_user is null then raise exception 'Authentication required'; end if; if coalesce(length(trim(p_customer_name)),0)<2 then raise exception 'Customer name is required'; end if; if coalesce(length(trim(p_customer_phone)),0)<6 then raise exception 'Customer phone is required'; end if; if coalesce(length(trim(p_delivery_address)),0)<8 then raise exception 'Delivery address is required'; end if; if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 or jsonb_array_length(p_items)>50 then raise exception 'Cart is empty or too large'; end if; for v_item in select value from jsonb_array_elements(p_items) loop v_product_id:=(v_item->>'product_id')::uuid; v_quantity:=(v_item->>'quantity')::integer; if v_quantity is null or v_quantity<1 or v_quantity>99 then raise exception 'Invalid quantity'; end if; select * into v_product from public.shop_products where id=v_product_id and is_active=true for update; if not found then raise exception 'Product is unavailable'; end if; if v_product.inventory_count-v_product.reserved_count<v_quantity then raise exception 'Insufficient stock for %',v_product.name; end if; v_subtotal:=v_subtotal+round(v_product.price_usd*v_quantity,2); end loop; insert into public.shop_orders(customer_user_id,customer_name,customer_phone,delivery_address,notes,subtotal_usd,total_usd) values(v_user,trim(p_customer_name),trim(p_customer_phone),trim(p_delivery_address),nullif(trim(p_notes),''),v_subtotal,v_subtotal) returning id,order_number into v_order_id,v_order_number; for v_item in select value from jsonb_array_elements(p_items) loop v_product_id:=(v_item->>'product_id')::uuid; v_quantity:=(v_item->>'quantity')::integer; select * into v_product from public.shop_products where id=v_product_id for update; v_line:=round(v_product.price_usd*v_quantity,2); insert into public.shop_order_items(order_id,product_id,sku,product_name,image_url,unit_price_usd,quantity,line_total_usd) values(v_order_id,v_product.id,v_product.sku,v_product.name,v_product.image_url,v_product.price_usd,v_quantity,v_line); update public.shop_products set reserved_count=reserved_count+v_quantity,updated_at=now() where id=v_product.id; end loop; return query select v_order_id,v_order_number,v_subtotal; end; $$;
revoke all on function public.shop_place_order(jsonb,text,text,text,text) from public,anon; grant execute on function public.shop_place_order(jsonb,text,text,text,text) to authenticated;
insert into public.shop_products(sku,slug,name,name_ckb,name_ar,description,description_ckb,description_ar,category,image_url,price_usd,compare_at_usd,inventory_count,featured,sort_order,metadata) values ('GC-TRAVEL-001','smart-travel-organizer','Smart Travel Organizer','ڕێکخەری زیرەکی گەشت','منظم السفر الذكي','Compact organizer for cables, passports and travel essentials.','ڕێکخەرێکی کەم‌قەبارە بۆ کەیبڵ، پاسپۆرت و پێداویستییەکانی گەشت.','منظم مدمج للكابلات وجوازات السفر ومستلزمات السفر.','travel','/assets/shop/shop-hero-mobile-catalog.png',18,24,30,true,10,'{"badge":"Best seller"}'),('GC-HOME-002','premium-storage-box','Premium Storage Box','سندووقی هەڵگرتنی پریمیۆم','صندوق تخزين فاخر','Durable stackable storage for home, office or warehouse.','سندووقی بەهێز و یەک‌لەسەر‌یەک بۆ ماڵ، ئۆفیس یان کۆگا.','صندوق تخزين متين قابل للتكديس للمنزل أو المكتب أو المستودع.','home','/assets/shop/shop-hero-mobile-warehouse.png',22,29,45,false,20,'{"badge":"New"}'),('GC-ELEC-003','usb-c-power-kit','USB-C Power Kit','کیتی وزەی USB-C','طقم طاقة USB-C','Everyday charging kit with cable and travel adapter.','کیتی شارژکردنی ڕۆژانە لەگەڵ کەیبڵ و ئەداپتەری گەشت.','طقم شحن يومي مع كابل ومحول سفر.','electronics','/assets/shop/globall-cloud-mobile-ui-cleaner.png',16.5,21,60,true,30,'{"badge":"Popular"}'),('GC-OFFICE-004','desk-setup-kit','Desk Setup Kit','کیتی ڕێکخستنی مێز','طقم تنظيم المكتب','Minimal desk accessories for a cleaner work setup.','کەرەستەی سادەی مێز بۆ شوێنێکی کارکردنی پاکتر.','إكسسوارات مكتب بسيطة لترتيب مساحة العمل.','office','/assets/shop/shop-hero-mobile-catalog.png',27,null,18,false,40,'{"badge":"Limited"}') on conflict(sku) do update set name=excluded.name,name_ckb=excluded.name_ckb,name_ar=excluded.name_ar,description=excluded.description,description_ckb=excluded.description_ckb,description_ar=excluded.description_ar,category=excluded.category,image_url=excluded.image_url,price_usd=excluded.price_usd,compare_at_usd=excluded.compare_at_usd,is_active=true,featured=excluded.featured,sort_order=excluded.sort_order,metadata=excluded.metadata,updated_at=now();
